(function(){'use strict';
var sheet=document.getElementById('sheet');if(!sheet)return;
function toast(msg){var t=document.createElement('div');t.textContent=msg;t.className='welog-save-toast';document.body.appendChild(t);setTimeout(function(){t.remove()},1800)}
function hideEditing(on){document.body.classList.toggle('welog-capturing',!!on)}
async function ready(){if(document.fonts&&document.fonts.ready)await document.fonts.ready;var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})}
async function canvasShot(){await ready();hideEditing(true);try{var w=Math.max(1,sheet.scrollWidth),h=Math.max(1,sheet.scrollHeight);if(window.html2canvas){return await window.html2canvas(sheet,{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#ffffff',logging:false,imageTimeout:30000,width:w,height:h,windowWidth:Math.max(document.documentElement.clientWidth,w),windowHeight:Math.max(document.documentElement.clientHeight,h),scrollX:-window.scrollX,scrollY:-window.scrollY,onclone:function(doc){doc.body.classList.add('welog-capturing');var s=doc.getElementById('sheet');if(s){s.style.visibility='visible';s.style.opacity='1'}doc.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate').forEach(function(n){n.style.display='none'})}})}throw new Error('html2canvas unavailable')}finally{hideEditing(false)}}
function modal(){var m=document.querySelector('.welog-reliable-preview');if(m)return m;m=document.createElement('div');m.className='welog-reliable-preview';m.hidden=true;m.innerHTML='<section><header><div><small>PREVIEW</small><b>저장 미리보기</b></div><button type="button">×</button></header><div class="welog-reliable-preview-body"><img alt="저장 미리보기"></div></section>';document.body.appendChild(m);m.addEventListener('click',function(e){if(e.target===m||e.target.closest('header button'))m.hidden=true});return m}
async function preview(){var m=modal(),im=m.querySelector('img');im.removeAttribute('src');m.hidden=false;try{var c=await canvasShot();im.src=c.toDataURL('image/png')}catch(e){console.error('preview failed',e);m.hidden=true;alert('미리보기를 만들지 못했습니다.')}}
async function save(){var b=document.getElementById('printBtn'),old=b&&b.textContent;if(b){b.disabled=true;b.textContent='저장 중…'}try{var c=await canvasShot(),blob=await new Promise(function(r){c.toBlob(r,'image/png')});if(!blob)throw new Error('empty blob');var url=URL.createObjectURL(blob),a=document.createElement('a'),name='WeLog';try{var s=JSON.parse(localStorage.getItem('welog-pair-sheet-v4')||'{}');name=(s.pairName||name).trim()||name}catch(e){}a.href=url;a.download=name+'.png';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},3000);toast('PNG 저장이 완료되었습니다!')}catch(e){console.error('save failed',e);alert('PNG 저장에 실패했습니다.')}finally{if(b){b.disabled=false;b.textContent=old}}}
function replace(id,fn){var old=document.getElementById(id);if(!old)return;var b=old.cloneNode(true);old.replaceWith(b);b.id=id;b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();fn()},true)}
function install(){replace('previewBtn',preview);replace('printBtn',save)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else setTimeout(install,0);
})();